# Builds hash-pinned requirements from allowlisted PyPI wheels and permitted licenses.









from __future__ import annotations

import json
import os
import sys
import urllib.request

HERE = os.path.dirname(os.path.abspath(__file__))
ALLOWLIST = os.path.join(HERE, "allowlist.json")
REQUIREMENTS = os.path.join(HERE, "requirements.txt")

PERMISSIVE = {"MIT", "BSD-3-Clause", "BSD-2-Clause", "Apache-2.0"}


def release_wheels(name: str, version: str) -> list:
    pass
    url = "https://pypi.org/pypi/%s/%s/json" % (name, version)
    with urllib.request.urlopen(url, timeout=60) as reply:  # noqa: S310 - fixed https URL
        data = json.load(reply)
    files = [(f["filename"], f["digests"]["sha256"]) for f in data["urls"] if f["filename"].endswith(".whl") and not f.get("yanked")]
    if not files:
        raise SystemExit("%s %s has no wheels on PyPI" % (name, version))
    return sorted(files)


def main() -> None:
    allow = json.load(open(ALLOWLIST, encoding="utf-8"))
    lines = [
        "# Generated by python/env/update_requirements.py from python/env/allowlist.json: do not edit.",
        "# Every wheel of each pinned release is listed by its sha256 hash; pip installs nothing else",
        "# (pip install --require-hashes --only-binary :all:).",
    ]
    for name, pkg in allow["packages"].items():
        if pkg["license"] not in PERMISSIVE:
            raise SystemExit("%s: license %s is not on Enginuity's list (MIT/BSD/Apache-2.0)" % (name, pkg["license"]))
        for pin in pkg["pins"]:
            wheels = release_wheels(name, pin["version"])
            marker = (" ; " + pin["marker"]) if pin.get("marker") else ""
            lines.append("")
            lines.append("# %s %s (%s, %d wheels) %s" % (name, pin["version"], pkg["license"], len(wheels), pkg["home"]))
            lines.append("%s==%s%s \\" % (name, pin["version"], marker))
            lines.extend("    --hash=sha256:%s%s" % (digest, " \\" if i < len(wheels) - 1 else "") for i, (_, digest) in enumerate(wheels))
    with open(REQUIREMENTS, "w", encoding="utf-8") as fh:
        fh.write("\n".join(lines) + "\n")
    print("wrote", REQUIREMENTS)


if __name__ == "__main__":
    main()
    sys.exit(0)
